  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00080",
          "explanation": "Doctor explains eGFR/creatinine risk in plain language, frames testing as risk prevention, and avoids alarmist dialysis declarations.",
          "quote": "肌酐330＋尿很少，说明肾功能确实明显异常，而且像是在原来肾不好的基础上又加重了。"
        },
        {
          "event_id": "lite_evt_00934",
          "explanation": "Doctor provides a short, understandable, non-alarmist summary for the family to use when the patient refuses, adapting to their fear of hospitalization.",
          "quote": "不是不用透析就安全了，是现在在医院盯着、用药顶着，所以暂时还没到透析那一步；一旦回家，钾、酸中毒、尿量这些变化没人盯，就不安全。"
        }
      ],
      "completion": "complete",
      "explanation": "HO1 is triggered by the worried, hesitant family with incomplete documents and low adherence. The doctor uses plain Chinese explanations tying urine decrease, edema, and CKD to medication-safety monitoring, frames testing as risk prevention rather than punishment, and provides a short actionable plan with teach-back from the family confirming understanding.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
